    function SpecialCharacters(spread, paramters) {
        var picker = window.specialCharacterPicker;
        if(picker){
            if(picker.expand){
                picker.hide();
            }else{
                picker.show();
            }
        }else{
            picker =  new SpecialCharacterPicker({
                target: document.getElementById("special-characters"),
                width:200,
                addCharacter: item => {
                   let sheet = spreadNS.Designer.wrapper.spread.getActiveSheet();
                   let editingText = (sheet.getValue(sheet.getActiveRowIndex(),sheet.getActiveColumnIndex()) || '') + item.specialCharacter;
                   let richText = []; 
                   let style =sheet.getStyle(sheet.getActiveRowIndex(),sheet.getActiveColumnIndex()) || new GC.Spread.Sheets.Style();
                   for(let i = 0; i < editingText.length; i++){
                       let code = editingText[i].charCodeAt();
                       if(code >= 57344){
                           let fontElement = $("<span></span>");
                           fontElement.css("font", style.font || '9pt 宋体' );
                           fontElement.css("font-family", 'sunway-font');
                           style.font = fontElement.css("font");
                           fontElement = null;
                       }
           
                       richText.push({
                           style: style,
                           text:  editingText[i]
                       });
                   }
                   
                     sheet.setValue(sheet.getActiveRowIndex(),sheet.getActiveColumnIndex(), {richText});
                },
            })
        }
    }

    spreadActions.SpecialCharacters = SpecialCharacters;
