            var self = this;
            var selections = self.getSelections();
            if (!selections || selections.length === 0) {
                return;
            }
            if (selections.length > 1) {
                designer.MessageBox.show(designer.res.NotExecInMultiRanges, designer.res.title, 3 /* error */);
                return false;
            }
            var selection = selections[0];
