     FlowInfoDialog.prototype._init = function () {
         var self = this;
         this._element.find(".addFlowInfo-button").click(function () {
             self._showEditFlowInfoDialog("new", null);
         });
     };
     FlowInfoDialog.prototype._initOptions = function () {
         var self = this;

         return {
             title: designer.res.flowInfoDialog.title,
             resizable: false,
             autoOpen: false,
             width: 'auto',
             modal: true,
             preventDefaultOkButton: true,
             buttons: [
                 {
                     text: designer.res.ok,
                     click: function () {
                         self._applySetting();
                         self.close();
                     }
                 },
                 {
                     text: designer.res.cancel,
                     click: function () {
                         self.close();
                     }
                 }
             ]
         };
     };

     FlowInfoDialog.prototype._beforeOpen = function (args) {
         var self = this;
         var sheet = designer.wrapper.spread.getActiveSheet();
         var selection = sheet.getSelections()[0];

         var sheetTag = sheet.tag();
         this._element.dialog('option', 'title', designer.res.flowInfoDialog.sheetTagTitle);
         var tbody = this._element.find('tbody');
         tbody.html("");
         if (sheetTag && sheetTag["flowInfo"]) {
             this._flowInfo = JSON.parse(JSON.stringify(sheetTag["flowInfo"]));
             for (var p in this._flowInfo) {
                 var info = this._flowInfo[p];
                 if (!info) continue;

                 this._addRow(info, tbody);
             }
         } else {
             this._flowInfo = {};
         }

         if (selection) {
             var cellTag = sheet.getRange(selection.row, selection.col, selection.rowCount, selection.colCount).tag() || "";
             try {
                 var cellTagObj = cellTag;
                 if (typeof cellTag === "string" && String(cellTag).trim().indexOf("{") == 0) {
                     cellTagObj = JSON.parse(cellTag);
                 }
                 if (cellTagObj && cellTagObj.mergeType == 1) {
                     this._element.find('#mergeType_0').prop("checked", true);
                 } else {
                     this._element.find('#mergeType_0').prop("checked", false);
                 }
             }
             catch (err) {
                 this._element.find('#mergeType_0').prop("checked", false);
             }
         }
     };

     FlowInfoDialog.prototype._generateRowTd = function (tr, info) {
         var self = this;
         tr.append("<td>" + info.flowName + "</td>");//列表标题
         tr.append("<td>" + (String(info.type) == "1" ? "列浮动" : "行浮动") + "</td>");//浮动类型
         tr.append("<td>" + info.startCell + "</td>");//起始单元格
         tr.append("<td>" + info.rowCount + "</td>");//行数
         tr.append("<td>" + info.colCount + "</td>");//列数
         tr.append("<td>" + info.bindingPathPrefix + "</td>");//绑定数据
         tr.append("<td>" + info.dataKey + "</td>");//绑定字段
         tr.append("<td>" + info.refFlowInfo + "</td>");//关联浮动
         tr.append('<td><a class="opt_update" href="javascript:void(0);">修改</a>&nbsp;&nbsp; <a class="opt_delete" href="javascript:void(0);">删除</a></td>');//操作
         //修改
         tr.find(".opt_update").click(function () {
             var flowName = $(this).parent().parent().find("td:eq(0)").text();
             self._showEditFlowInfoDialog("update", self._flowInfo[flowName]);
         });

         //删除
         tr.find(".opt_delete").click(function () {
             var flowName = $(this).parent().parent().find("td:eq(0)").text();
             if (confirm("是否删除【" + flowName + "】浮动信息")) {
                 delete self._flowInfo[flowName];
             }
         });
     };
     FlowInfoDialog.prototype._addRow = function (info, tbody) {
         var self = this;
         var tbody = tbody || this._element.find('tbody');
         var tr = $("<tr class='tr_" + info.flowName + "'></tr>");
         self._generateRowTd(tr, info);
         tbody.append(tr);
     };

     FlowInfoDialog.prototype._updateRow = function (info, tbody) {
         var self = this;
         var tbody = tbody || this._element.find('tbody');
         var tr = tbody.find(".tr_" + info.flowName);
         tr.html("");
         self._generateRowTd(tr, info);
         //tbody.append(tr);
     };
     FlowInfoDialog.prototype._applySetting = function () {
         var sheet = designer.wrapper.spread.getActiveSheet();
         var tag = designer.wrapper.spread.getActiveSheet().tag();
         tag = tag || {};
         tag["flowInfo"] = this._flowInfo;

         if (this._flowInfo) {
             var flowInfo, msg, style;
             for (var p in this._flowInfo) {
                 flowInfo = this._flowInfo[p];

                 msg = flowInfo["type"] == "0" ? "↓" : "→";
                 msg += (flowInfo["bindingPathPrefix"] || "空") + "." + (flowInfo["dataKey"] || "空");
                 style = sheet.getStyle(flowInfo.row, flowInfo.col) || new GC.Spread.Sheets.Style();
                 style.watermark = msg;
                 sheet.setStyle(flowInfo.row, flowInfo.col, style);
             }
         }
         designer.actions.doAction('setTag', designer.wrapper.spread, [tag, "sheet"]);

         if (this._element.find('#mergeType_0').prop("checked")) {
             designer.actions.doAction('setTag', designer.wrapper.spread, [{ "mergeType": 1 }, "cell"]);
         } else {
             designer.actions.doAction('setTag', designer.wrapper.spread, [null, "cell"]);
         }
     };
     return FlowInfoDialog;
