 var EditFlowInfoDialog = (function (_super) {
     designer.extends(EditFlowInfoDialog, _super);
     function EditFlowInfoDialog(parentDialog) {  // NOSONAR  noUseArguments
         _super.call(this, (dialogHtmlPath), '.edit-flow-info-dialog');
     }

     EditFlowInfoDialog.prototype._initOptions = function () {
         var self = this;
         return {
             title: designer.res.flowInfoDialog.editWinTitle,
             resizable: false,
             autoOpen: false,
             width: 'auto',
             modal: true,
             preventDefaultOkButton: true,
             buttons: [
                 {
                     text: designer.res.ok,
                     click: function () {
                         if (self._applySetting()) {
                             self.close();
                         }
                     }
                 },
                 {
                     text: designer.res.cancel,
                     click: function () {
                         self.close();
                     }
                 }
             ]
         };
     };

     EditFlowInfoDialog.prototype._beforeOpen = function (args) {
         var self = this;
         var sheet = designer.wrapper.spread.getActiveSheet();

         this._element.find('.text-flowName').prop("disabled", false)
         this._element.find('input:radio[name=flowType]').prop("checked", false);
         this._element.find('.text-flowName').val("");
         this._element.find('.text-startCell').val("");
         this._element.find('.text-rowCount').val("2");
         this._element.find('.text-colCount').val("0");
         this._element.find('.text-bindingPathPrefix').val("");
         this._element.find('.text-dataKey').val("");
         this._element.find('.text-refFlowInfo').val("");

         this.__opt = args[0];
         var values = args[1];
         this.__flowInfoMap = args[2];
         this.__pFlowInfoDialog = args[3];

         if (values) {
             this._element.find('.text-flowName').prop("disabled", true)
             this._element.find('input:radio[name=flowType][value=' + values.type + ']').prop("checked", true);
             this._element.find('.text-flowName').val(values.flowName);
             this._element.find('.text-startCell').val(values.startCell);
             this._element.find('.text-rowCount').val(values.rowCount);
             this._element.find('.text-colCount').val(values.colCount);
             this._element.find('.text-bindingPathPrefix').val(values.bindingPathPrefix);
             this._element.find('.text-dataKey').val(values.dataKey);
             this._element.find('.text-refFlowInfo').val(values.refFlowInfo);
         } else {
             this._element.find('input:radio[name=flowType][value=0]').prop("checked", true);
         }
     };
     EditFlowInfoDialog.prototype._applySetting = function () {

         var startCell = this._element.find('.text-startCell').val();
         var sheet = designer.wrapper.spread.getActiveSheet();
         var range = GC.Spread.Sheets.CalcEngine.formulaToRange(sheet, startCell, 0, 0);
         if (!range) {
             alert("起始单元格无效");
             return false;
         }
         var flowName = this._element.find('.text-flowName').val().replace(/ /g, "");

         var info = {
             type: this._element.find('input:radio[name=flowType]:checked').val(),
             flowName: flowName,
             startCell: startCell,
             row: range.row,
             col: range.col,
             rowCount: this._element.find('.text-rowCount').val(),
             colCount: this._element.find('.text-colCount').val(),
             bindingPathPrefix: this._element.find('.text-bindingPathPrefix').val(),
             dataKey: this._element.find('.text-dataKey').val(),
             refFlowInfo: this._element.find('.text-refFlowInfo').val()
         };

         if (this.__opt == "new" && this.__flowInfoMap[info.flowName]) {
             alert("浮动名称【" + info.flowName + "】已存在");
             return false;
         }

         info.rowCount = !isNaN(info.rowCount) ? parseInt(info.rowCount) : 0;
         info.colCount = !isNaN(info.colCount) ? parseInt(info.colCount) : 0;

         if (this.__flowInfoMap[info.flowName]) {
             this.__pFlowInfoDialog._updateRow(info);
         } else {
             this.__pFlowInfoDialog._addRow(info);
         }
         this.__flowInfoMap[info.flowName] = info;
         return true;
     };
     return EditFlowInfoDialog;
 })(designer.BaseDialog);
 designer.EditFlowInfoDialog = EditFlowInfoDialog;
