                         var fill = $("#formulaBarText");
                         if (txt.substring(0, 1) !== "=") {
                             txt = "=" + txt;
                         }
                         fill.text(txt);
                         var sheet = designer.wrapper.spread.getActiveSheet();
                         var value = {
                             txt: txt,
                             activeRowIndex: sheet.getActiveRowIndex(),
                             activeColumnIndex: sheet.getActiveColumnIndex()
                         };
