                                    var x = allColumns.filter(function(elt, i, array) {
                                        return elt == item.key;
                                    });
                                    if (!x || x.length == 0) {
                                        var o = {};
                                        o.name = item.key;
                                        o.dataField = item.key;
                                        newColumns.push(o)
                                    }
