/**
 * 获取url参数
 */
function queryUrlValueByName(name) {
    var reg = new RegExp("(^|&)" + name + "=([^&]*)(&|$)");
    var r = window.location.search.substr(1).match(reg);
    if (r != null)
        return unescape(decodeURI(r[2]));
    return null;
}

/**
     * 获取url后面的参数
     * @returns {{}}
     */
function getUrlParams() {
    var url = location.search;
    var params = {};
    if (url.indexOf("?") !== -1) {
        var strs = url.substr(1).split("&");
        for (var i = 0; i < strs.length; i++) {
            params[strs[i].split("=")[0]] = decodeURIComponent(strs[i].split("=")[1]);
        }
    }
    return params;
}

/**
 * 查看字符串是否为空
 */
function isEmpty(obj) {
    if (obj === null)
        return true;
    if (typeof obj === 'undefined') {
        return true;
    }
    if (typeof obj === 'string') {
        if (obj === "") {
            return true;
        }
        var reg = new RegExp("^([ ]+)|([　]+)$");
        return reg.test(obj);
    }
    return false;
}

/**
 * 精确JS乘法计算
 */
function jsPlusMul(arg1, arg2) {
    var m = 0, s1 = arg1.toString(), s2 = arg2.toString();
    try {
        m += s1.split(".")[1].length;
    } catch (e) {
    }
    try {
        m += s2.split(".")[1].length;
    } catch (e) {
    }
    return Number(s1.replace(".", "")) * Number(s2.replace(".", ""))
            / Math.pow(10, m);
}

/**
 * 精确JS除法计算
 */
function jsPlusDiv(arg1, arg2) {
    var t1 = 0, t2 = 0, r1, r2;
    try {
        t1 = arg1.toString().split(".")[1].length;
    } catch (e) {
    }
    try {
        t2 = arg2.toString().split(".")[1].length;
    } catch (e) {
    }
    with (Math) {
        r1 = Number(arg1.toString().replace(".", ""));
        r2 = Number(arg2.toString().replace(".", ""));
        return (r1 / r2) * pow(10, t2 - t1);
    }
}

/**
 * 禁止页面使用F5刷新
 * */
function disableF5(event) {
    if (event) {
        var keyCode = event.keyCode ? event.keyCode
                : event.which ? event.which : event.charCode;
        if (keyCode == 116) {
            event.keyCode = 0;
            event.returnValue = false;
            return false
        }
    }
}

/**
 * 补齐有效位数（针对末尾小数点）
 * */
function supplementValidDigit(value, places) {
    var isnegative = 0;

    if (value < 0) {
        value = -value;
        isnegative = 1;
    }

    var valueStr = String(value);
    var dot = valueStr.indexOf(".");
    var length = valueStr.length;
    if (dot > 0) {
        if (value > 1) {
            if ((length - 1) < places) {
                for (var i = 0; i < (places - length + 1) ; i++) {
                    valueStr += '0';
                }
            }
        } else {
            for (var i = (dot + 1) ; i < length; i++) {
                var v = valueStr.charAt(i);
                if (parseInt(v) > 0) {
                    if (length - i < places) {
                        for (var j = 0; j < (places - length + i) ; j++) {
                            valueStr += '0';
                        }
                    }
                    break;
                }
            }
        }
    } else {
        if (length < places) {
            valueStr += '.';
            for (var i = 0; i < (places - length) ; i++) {
                valueStr += '0';
            }
        }
    }

    if (isnegative == 1) {
        valueStr = "-" + valueStr;
    }
    if (places == 0 && valueStr.length > 0 && valueStr.substring(valueStr.length - 1, valueStr.length) == ".") {
        valueStr = valueStr.substring(0, valueStr.length - 1)
    }
    return valueStr;
}

/**
 * 关闭窗口--当eln页面刷新后不能关闭
 */
function closeWP() {
    var Browser = navigator.appName;
    var indexB = Browser.indexOf('Explorer');

    if (indexB > 0) {
        var indexV = navigator.userAgent.indexOf('MSIE') + 5;
        var Version = navigator.userAgent.substring(indexV, indexV + 1);

        if (Version >= 7) {
            window.open('', '_self', '');
            window.close();
        } else if (Version == 6) {
            window.opener = null;
            window.close();
        } else {
            window.opener = '';
            window.close();
        }

    } else {
        window.close();
    }
}
/**
* 点击数值的时候-将如果是字符串类型的数字 格式化成 数值
*/
function formatnumber(spread) {
    var activeSheet = spread.getActiveSheet();
    var selectedRanges = activeSheet.getSelections();
    for (var i = 0; i < selectedRanges.length; i++) {
        var row = selectedRanges[i].row;
        var col = selectedRanges[i].col;
        var rowc = selectedRanges[i].rowCount;
        var colc = selectedRanges[i].colCount;
        for (var m = 0; m < rowc; m++)
            for (var n = 0; n < colc; n++) {
                var cell = activeSheet.getCell(row + m, col + n);
                var str = activeSheet.getValue(row + m, col + n);
                if (typeof (str) == "number")
                    continue;
                var k = Number(str);
                if (!isNaN(k)) {
                    activeSheet.suspendPaint();
                    activeSheet.setValue(row + m, col + n, k);
                    activeSheet.resumePaint();
                }
            }
    }
}
