        updateUndoRedo();
        updateCellStyle();
        updateFormat();
        updateMerge();
        updateSparkline();
        updateTable();
        updateShowHide();
        updateProtectLock();
        hideSlicerTab();
        resetSpreadNamedStyle();
        exitTemplateDesignMode();
        isModified = false;
